import{_ as e,o as a,c as i,an as r}from"./chunks/framework.BMe1Ravt.js";const p=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md","lastUpdated":null}'),d={name:"architecture.md"};function n(l,t,s,o,h,g){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="Architecture" tabindex="-1">Architecture <a class="header-anchor" href="#Architecture" aria-label="Permalink to &quot;Architecture {#Architecture}&quot;">​</a></h1><p>Kraken is a <strong>GPU-first, method-agnostic PDE framework</strong> written in Julia. The discretization method is a <em>pluggable backend</em> selected in the <code>.krk</code> case file, not a hard-wired property of the solver. Every method is meant to share the same <strong>problem / solution / observable</strong> contract, so the case description — geometry, boundary conditions, units, and requested output — stays identical no matter which method runs underneath.</p><p>Today, <strong>the Lattice Boltzmann Method (LBM) is the mature production method</strong>: it is the one path that is shipped and validated across the v0.2 benchmark suite. Structured-grid finite-volume / finite-difference co-solvers, for the steady and elliptic regimes that explicit LBM cannot reach efficiently, are on the roadmap — not finished.</p><p>This page is the honest map of where each capability stands. Nothing below the <strong>Stable</strong> tier should be read as delivered.</p><h2 id="Maturity" tabindex="-1">Maturity <a class="header-anchor" href="#Maturity" aria-label="Permalink to &quot;Maturity {#Maturity}&quot;">​</a></h2><p>The framework is organised in three tiers. The <code>Status</code> column is the contract: <strong>Stable</strong> means shipped and validated in v0.2; <strong>Experimental</strong> means the code is present but validation is partial or undocumented; <strong>Planned</strong> means designed or scoped but not shipped.</p><h3 id="Stable-—-shipped-and-validated-in-v0.2" tabindex="-1">Stable — shipped and validated in v0.2 <a class="header-anchor" href="#Stable-—-shipped-and-validated-in-v0.2" aria-label="Permalink to &quot;Stable — shipped and validated in v0.2 {#Stable-—-shipped-and-validated-in-v0.2}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Capability</th><th style="text-align:right;">Status</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;">LBM core</td><td style="text-align:right;">Stable</td><td style="text-align:right;">D2Q9 / D3Q19, BGK; D2Q9 MRT; Guo body forces; axisymmetric</td></tr><tr><td style="text-align:right;">Thermal</td><td style="text-align:right;">Stable</td><td style="text-align:right;">double-distribution / Boussinesq, 2D and 3D</td></tr><tr><td style="text-align:right;">Viscoelastic</td><td style="text-align:right;">Stable</td><td style="text-align:right;">Oldroyd-B (2D, log-conformation)</td></tr><tr><td style="text-align:right;">Boundary conditions</td><td style="text-align:right;">Stable</td><td style="text-align:right;">spatial, Zou-He, bounce-back, periodic</td></tr><tr><td style="text-align:right;">Grid refinement</td><td style="text-align:right;">Stable</td><td style="text-align:right;">Filippova–Hänel (2D full, 3D partial)</td></tr><tr><td style="text-align:right;">Geometry</td><td style="text-align:right;">Stable</td><td style="text-align:right;">STL + voxelization, embedded boundaries</td></tr><tr><td style="text-align:right;">Units &amp; DSL</td><td style="text-align:right;">Stable</td><td style="text-align:right;">units system; <code>.krk</code> DSL + CLI</td></tr><tr><td style="text-align:right;">Backends</td><td style="text-align:right;">Stable</td><td style="text-align:right;">CPU, CUDA, Metal via KernelAbstractions</td></tr><tr><td style="text-align:right;">Output</td><td style="text-align:right;">Stable</td><td style="text-align:right;">VTK / PNG / GIF</td></tr></tbody></table><h3 id="Experimental-—-code-present,-partial-or-undocumented-validation" tabindex="-1">Experimental — code present, partial or undocumented validation <a class="header-anchor" href="#Experimental-—-code-present,-partial-or-undocumented-validation" aria-label="Permalink to &quot;Experimental — code present, partial or undocumented validation {#Experimental-—-code-present,-partial-or-undocumented-validation}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Capability</th><th style="text-align:right;">Status</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;">3D thermal + refinement combined</td><td style="text-align:right;">Experimental</td><td style="text-align:right;">known divergence</td></tr><tr><td style="text-align:right;">Generalised-Newtonian / other viscoelastic models</td><td style="text-align:right;">Experimental</td><td style="text-align:right;">power-law, Carreau, Cross, Bingham, Herschel–Bulkley, FENE-P, Saramito — 2D, beyond Oldroyd-B</td></tr><tr><td style="text-align:right;">Outflow / Neumann / symmetry BCs</td><td style="text-align:right;">Experimental</td><td style="text-align:right;">partial</td></tr><tr><td style="text-align:right;">Multi-level nested refinement patches</td><td style="text-align:right;">Experimental</td><td style="text-align:right;">parser supports, partially tested</td></tr></tbody></table><h3 id="Planned-—-on-the-roadmap,-NOT-shipped" tabindex="-1">Planned — on the roadmap, NOT shipped <a class="header-anchor" href="#Planned-—-on-the-roadmap,-NOT-shipped" aria-label="Permalink to &quot;Planned — on the roadmap, NOT shipped {#Planned-—-on-the-roadmap,-NOT-shipped}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Capability</th><th style="text-align:right;">Status</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;">Method-agnostic platform contract</td><td style="text-align:right;">Planned</td><td style="text-align:right;"><code>solve</code> / <code>sample</code> / <code>observe</code></td></tr><tr><td style="text-align:right;">Steady incompressible Navier–Stokes</td><td style="text-align:right;">Planned</td><td style="text-align:right;">structured FV/FD method (SIMPLE) for the elliptic regime (<a href="https://github.com/lauguimel/Kraken.jl/issues/7" target="_blank" rel="noreferrer">issue #7</a>)</td></tr><tr><td style="text-align:right;">Shared GPU linear-solve service</td><td style="text-align:right;">Planned</td><td style="text-align:right;">matrix-free Poisson (<a href="https://github.com/lauguimel/Kraken.jl/issues/8" target="_blank" rel="noreferrer">issue #8</a>)</td></tr><tr><td style="text-align:right;">Geometry/shape automatic differentiation</td><td style="text-align:right;">Planned</td><td style="text-align:right;">steady shape-adjoint</td></tr><tr><td style="text-align:right;">Curvilinear / multi-block grids</td><td style="text-align:right;">Planned</td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;">Multiphase</td><td style="text-align:right;">Planned</td><td style="text-align:right;">VOF / phase-field / Shan-Chen / species</td></tr><tr><td style="text-align:right;">Additional GPU backends</td><td style="text-align:right;">Planned</td><td style="text-align:right;">ROCm / oneAPI</td></tr></tbody></table><p><strong>Out of scope:</strong> unstructured FEM/DG; general unstructured-mesh FV CFD; CAD mesh authoring.</p><h2 id="Choosing-a-method" tabindex="-1">Choosing a method <a class="header-anchor" href="#Choosing-a-method" aria-label="Permalink to &quot;Choosing a method {#Choosing-a-method}&quot;">​</a></h2><p>In the intended design, the discretization method is a <code>.krk</code> choice, not a fork of the codebase. New physics and new methods drop in as modules behind the shared problem / solution / observable contract, so a case written for one method needs no rewrite to target another.</p><p>State plainly what that means <strong>today</strong>: the only production method is LBM. The structured FV/FD steady path and the method-agnostic platform contract itself are on the roadmap (see the <strong>Planned</strong> tier above), not finished. The framing is the direction of travel; the <strong>Stable</strong> table is what v0.2 actually ships.</p>',16)])])}const u=e(d,[["render",n]]);export{p as __pageData,u as default};
